/** Arithmetic over validated saved observations, never inferred continuous monitoring. */
final class AnalysisHealthSummary {
    static Double mean(List<Double> values){if(values.isEmpty())return null;double sum=0;for(double v:values)sum+=v;return sum/values.size();}
    static Double quantile(List<Double> values,double p){if(values.isEmpty())return null;ArrayList<Double> sorted=new ArrayList<>(values);Collections.sort(sorted);double position=(sorted.size()-1)*p;int lo=(int)Math.floor(position),hi=(int)Math.ceil(position);return sorted.get(lo)+(sorted.get(hi)-sorted.get(lo))*(position-lo);}
    static Double sd(List<Double> values){if(values.size()<2)return null;double mean=mean(values),sum=0;for(double v:values)sum+=(v-mean)*(v-mean);return Math.sqrt(sum/(values.size()-1));}
    static Number round(Double value,int digits){if(value==null||!Double.isFinite(value))return null;java.math.BigDecimal rounded=java.math.BigDecimal.valueOf(value).setScale(digits,java.math.RoundingMode.HALF_UP);if(digits==0)return rounded.longValueExact();return rounded.doubleValue();}
    static void build(AnalysisSnapshot.Builder b,String domain){if("sleep".equals(domain))sleep(b);else observations(b,domain);}
    private static void observations(AnalysisSnapshot.Builder b,String name){AnalysisSnapshot.Selection s=b.selection;Map<Integer,List<Double>> days=new java.util.TreeMap<>();Map<Integer,List<Long>> stamps=new HashMap<>();int excluded=0,partial=0;String unit="heart".equals(name)?"bpm":"%",suffix="heart".equals(name)?"Bpm":"Percent";for(ExpansionModels.HealthRecord r:b.source.health.getOrDefault(name,Collections.emptyList())){boolean valid=r.validity.startsWith("VALID")&&r.value!=null&&Double.isFinite(r.value)&&unit.equals(r.data.optString("unit"))&&r.tsSeconds>0&&r.tsSeconds<=r.receivedAt/1000&&("heart".equals(name)?r.value>=20&&r.value<=300:r.value>0&&r.value<=100);if(!valid){excluded++;continue;}int index=s.index(Instant.ofEpochSecond(r.tsSeconds).atZone(s.zone).toLocalDate());if(index>0||index<(s.compare?-2*s.days+1:-s.days+1)){excluded++;continue;}days.computeIfAbsent(index,k->new ArrayList<>()).add(r.value);stamps.computeIfAbsent(index,k->new ArrayList<>()).add(r.tsSeconds);if(!"COMPLETE".equals(r.pageState)&&s.current(index))partial++;}List<Double> pooled=new ArrayList<>(),currentMedians=new ArrayList<>(),previousMedians=new ArrayList<>();for(Map.Entry<Integer,List<Double>> d:days.entrySet()){if(s.current(d.getKey())){pooled.addAll(d.getValue());currentMedians.add(quantile(d.getValue(),.5));}else previousMedians.add(quantile(d.getValue(),.5));}
        JSONObject domain=b.domain(name,currentMedians.size(),"LIMITED","PARTIAL_HISTORY","SPARSE_OBSERVATIONS");b.common(domain,currentMedians.size(),currentMedians.size(),excluded,pooled.size());b.metric(domain,"period.pooledMedian"+suffix,round(quantile(pooled,.5),1),unit,"median_all_valid_saved_points",pooled.size());if("heart".equals(name))b.metric(domain,"period.pooledMeanBpm",round(mean(pooled),1),unit,"sum_all_valid_values_divided_by_count",pooled.size());b.metric(domain,"period.meanDailyMedian"+suffix,round(mean(currentMedians),1),unit,"equal_weight_mean_observed_day_medians",currentMedians.size());b.metric(domain,"period.partialPageRecordCount",partial,"count","partial_page_records_not_monitoring_coverage",pooled.size());
        for(Map.Entry<Integer,List<Double>> d:days.entrySet()){int index=d.getKey();List<Double> values=d.getValue();if(s.current(index)&&!s.end.equals(java.time.LocalDate.now(s.zone))||s.current(index)&&index<0)b.daily.get(name).put(index,quantile(values,.5));if(!s.focused&&s.days!=1)continue;String path="day["+index+"].";b.metric(domain,path+"sampleCount",values.size(),"count","valid_saved_observations",values.size());b.metric(domain,path+"min"+suffix,round(Collections.min(values),1),unit,"minimum_registered_point",values.size());b.metric(domain,path+"median"+suffix,round(quantile(values,.5),1),unit,"daily_observation_median",values.size());b.metric(domain,path+"mean"+suffix,round(mean(values),1),unit,"daily_observation_mean",values.size());b.metric(domain,path+"max"+suffix,round(Collections.max(values),1),unit,"maximum_registered_point",values.size());b.metric(domain,path+("heart".equals(name)?"sampleStdDevBpm":"sampleStdDevPercentagePoints"),round(sd(values),1),"heart".equals(name)?unit:"percentagePoints","sample_sd_n_minus_one",values.size());List<Long> times=stamps.get(index);b.metric(domain,path+"observedSpanSeconds",Collections.max(times)-Collections.min(times),"seconds","last_minus_first_timestamp_not_monitoring_duration",values.size());}
        int minimum=s.days==7?5:s.days==30?10:Integer.MAX_VALUE;boolean comparison=s.compare&&currentMedians.size()>=minimum&&previousMedians.size()>=minimum;if(comparison){b.comparison(domain,"meanDailyMedianDelta"+("heart".equals(name)?"Bpm":"PercentagePoints"),round(mean(currentMedians)-mean(previousMedians),1),"heart".equals(name)?"bpm":"percentagePoints","current_minus_previous_means_of_daily_medians",Math.min(currentMedians.size(),previousMedians.size()));b.metric(domain,"comparison.currentSampleCount",pooled.size(),"count","current_valid_points",pooled.size());int previousCount=0;for(Map.Entry<Integer,List<Double>> d:days.entrySet())if(!s.current(d.getKey()))previousCount+=d.getValue().size();b.metric(domain,"comparison.previousSampleCount",previousCount,"count","previous_valid_points",previousCount);}
        if("heart".equals(name)){workoutHeartPeriod(b,domain);workoutHeart(b,domain);b.question(domain,"HEART_OBSERVATION_DISTRIBUTION","HEART_WORKOUT_CONTEXT","HEART_DATA_COMPLETENESS");if(comparison)b.question(domain,"HEART_OBSERVED_LEVEL_CHANGE");}else{b.question(domain,"SPO2_OBSERVATION_VARIATION","SPO2_DATA_COMPLETENESS");if(comparison)b.question(domain,"SPO2_OBSERVED_LEVEL_CHANGE");}}
    private static void workoutHeart(AnalysisSnapshot.Builder b,JSONObject domain){int session=0;for(JSONObject workout:b.source.workouts){if(!"SAVED".equals(workout.optString("status"))||!ExpansionModels.PHONE.equals(workout.optString("source")))continue;int index=b.selection.index(AnalysisSnapshot.workoutDate(workout,b.selection.zone));String id=workout.optString("id");Map<String,JSONObject> segments=new HashMap<>();for(JSONObject segment:b.source.segments.getOrDefault(id,Collections.emptyList()))segments.put(segment.optString("id"),segment);List<Double> values=new ArrayList<>();Set<String> unique=new HashSet<>();int excluded=0;for(JSONObject o:b.source.observations.getOrDefault(id,Collections.emptyList())){Double value=AnalysisSnapshot.validNumber(o,"value",20,300);JSONObject segment=segments.get(o.optString("segmentId"));Long at=AnalysisSnapshot.number(o,"measuredAt",1,253402300799999L);boolean valid="HEART".equals(o.optString("kind"))&&"ACCEPTED".equals(o.optString("state"))&&"VALID".equals(o.optString("quality"))&&"bpm".equals(o.optString("unit"))&&value!=null&&segment!=null&&at!=null&&at>=segment.optLong("startAt")&&at<=segment.optLong("endAt",segment.optLong("lastAt"));if(!valid||!unique.add(at+":"+o.optString("rawSha256"))){excluded++;continue;}values.add(value);}if(!b.selection.focused&&b.selection.days!=1)continue;String path="workout[session"+(session++)+"].";b.metric(domain,path+"dayIndex",index,"dayIndex","relative_day",1);b.metric(domain,path+"sampleCount",values.size(),"count","accepted_valid_active_segment_observations",values.size());b.metric(domain,path+"meanBpm",round(mean(values),1),"bpm","sample_mean_not_time_weighted",values.size());b.metric(domain,path+"maxBpm",values.isEmpty()?null:round(Collections.max(values),1),"bpm","maximum_accepted_observation",values.size());b.metric(domain,path+"excludedRecordCount",excluded,"count","excluded_conflicting_or_outside_segment",excluded);b.metric(domain,path+"recoveryGapUnknown",workout.optBoolean("recoveryGapUnknown"),"boolean","saved_session_gap_flag",1);}}
    private static final class Episode {final ExpansionModels.HealthRecord r;final int index;final long enter,exit,asleep,awake,light,deep;final boolean unknown,clock;boolean overlap;Episode(ExpansionModels.HealthRecord r,AnalysisSnapshot.Selection s){this.r=r;enter=NutritionModels.integer(r.data,"enter",0,253402300799L);exit=NutritionModels.integer(r.data,"exit",enter+1,253402300799L);index=s.index(Instant.ofEpochSecond(exit).atZone(s.zone).toLocalDate());JSONArray intervals=NutritionModels.array(r.data,"intervals",1,4096);long a=0,w=0,l=0,d=0,u=0,previous=enter;for(int i=0;i<intervals.length();i++){JSONObject interval=NutritionModels.child(intervals,i);long start=NutritionModels.integer(interval,"start",enter,exit),end=NutritionModels.integer(interval,"end",start+1,exit),stage=NutritionModels.integer(interval,"rawStage",Integer.MIN_VALUE,Integer.MAX_VALUE);if(start!=previous)throw new IllegalArgumentException("SLEEP_INTERVAL_GAP");previous=end;long seconds=end-start;if(stage==0)w+=seconds;else if(stage==1||stage==2){a+=seconds;l+=seconds;}else if(stage==3){a+=seconds;d+=seconds;}else u+=seconds;}if(previous!=exit)throw new IllegalArgumentException("SLEEP_INTERVAL_END");asleep=a;awake=w;light=l;deep=d;unknown=u>0;clock=exit>r.receivedAt/1000||r.zone.isEmpty()||!r.zone.equals(s.zone.getId())||r.data.optBoolean("clockShift");}}
    private static void sleep(AnalysisSnapshot.Builder b){AnalysisSnapshot.Selection s=b.selection;List<Episode> episodes=new ArrayList<>();int excluded=0;for(ExpansionModels.HealthRecord r:b.source.health.getOrDefault("sleep",Collections.emptyList())){if(!r.validity.startsWith("VALID")){excluded++;continue;}try{Episode e=new Episode(r,s);if(e.index<=0&&e.index>=(s.compare?-2*s.days+1:-s.days+1))episodes.add(e);}catch(RuntimeException e){excluded++;}}if(episodes.size()>4096)throw new IllegalStateException("ANALYSIS_SOURCE_LIMIT");episodes.sort(java.util.Comparator.comparingLong(e->e.enter));for(int i=0;i<episodes.size();i++)for(int j=i+1;j<episodes.size();j++){Episode a=episodes.get(i),c=episodes.get(j);if(c.enter>=a.exit)break;a.overlap=true;c.overlap=true;}
        Map<Integer,Episode> selected=new java.util.TreeMap<>();Map<Integer,Integer> counts=new HashMap<>(),unknown=new HashMap<>(),eligibleCounts=new HashMap<>();int currentUnknown=0,currentConflicts=0,clock=0;for(Episode e:episodes){counts.merge(e.index,1,Integer::sum);if(e.unknown){unknown.merge(e.index,1,Integer::sum);if(s.current(e.index))currentUnknown++;excluded++;continue;}if(e.overlap){if(s.current(e.index))currentConflicts++;excluded++;continue;}if(e.clock)clock++;if(e.exit>e.r.receivedAt/1000){excluded++;continue;}eligibleCounts.merge(e.index,1,Integer::sum);Episode old=selected.get(e.index);if(old==null||e.asleep>old.asleep||e.asleep==old.asleep&&(e.exit>old.exit||e.exit==old.exit&&e.r.id.compareTo(old.r.id)>0))selected.put(e.index,e);}
        List<Double> current=new ArrayList<>(),previous=new ArrayList<>();for(Map.Entry<Integer,Episode> e:selected.entrySet())(s.current(e.getKey())?current:previous).add((double)e.getValue().asleep);JSONObject domain=b.domain("sleep",current.size(),"LIMITED","PARTIAL_HISTORY");b.common(domain,current.size(),current.size(),excluded,episodes.size());b.metric(domain,"period.unknownStageEpisodeCount",currentUnknown,"count","episodes_with_unconfirmed_stage",episodes.size());b.metric(domain,"period.conflictingOverlapEpisodeCount",currentConflicts,"count","overlapping_natural_key_episodes_excluded",episodes.size());b.metric(domain,"period.clockShiftExcludedCount",clock,"count","onset_exclusions_unknown_or_changed_zone_clock_flags_or_future_timestamp",episodes.size());b.metric(domain,"period.meanSelectedAsleepSeconds",round(mean(current),0),"seconds","mean_selected_eligible_episodes",current.size());b.metric(domain,"period.medianSelectedAsleepSeconds",round(quantile(current,.5),0),"seconds","median_selected_eligible_episodes",current.size());b.metric(domain,"period.q25SelectedAsleepSeconds",round(quantile(current,.25),0),"seconds","linear_quantile_position_n_minus_one",current.size());b.metric(domain,"period.q75SelectedAsleepSeconds",round(quantile(current,.75),0),"seconds","linear_quantile_position_n_minus_one",current.size());
        for(int index=s.compare?-2*s.days+1:-s.days+1;index<=0;index++){Episode e=selected.get(index);if(e!=null&&s.current(index)&&!(index==0&&s.end.equals(java.time.LocalDate.now(s.zone))))b.daily.get("sleep").put(index,(double)e.asleep);if(!s.focused&&s.days!=1)continue;String path="day["+index+"].";b.metric(domain,path+"episodeCount",counts.getOrDefault(index,0),"count","saved_episodes_by_exit_day",counts.getOrDefault(index,0));b.metric(domain,path+"eligibleEpisodeCount",eligibleCounts.getOrDefault(index,0),"count","known_stage_non_overlapping_episodes",eligibleCounts.getOrDefault(index,0));b.metric(domain,path+"unknownStageEpisodeCount",unknown.getOrDefault(index,0),"count","unknown_stage_episodes",counts.getOrDefault(index,0));b.metric(domain,path+"selectedAsleepSeconds",e==null?null:e.asleep,"seconds","sum_stage_1_2_3_end_minus_start",e==null?0:1);b.metric(domain,path+"selectedAwakeSeconds",e==null?null:e.awake,"seconds","sum_stage_0_end_minus_start",e==null?0:1);b.metric(domain,path+"selectedLightSeconds",e==null?null:e.light,"seconds","sum_stage_1_2_end_minus_start",e==null?0:1);b.metric(domain,path+"selectedDeepSeconds",e==null?null:e.deep,"seconds","sum_stage_3_end_minus_start",e==null?0:1);b.metric(domain,path+"selectedIntervalSeconds",e==null?null:e.exit-e.enter,"seconds","exit_minus_enter_not_time_in_bed",e==null?0:1);}
        int minimum=s.days==7?5:s.days==30?10:Integer.MAX_VALUE;boolean comparison=s.compare&&current.size()>=minimum&&previous.size()>=minimum;if(comparison)b.comparison(domain,"medianAsleepDeltaSeconds",round(quantile(current,.5)-quantile(previous,.5),0),"seconds","current_minus_previous_selected_episode_medians",Math.min(current.size(),previous.size()));List<Episode> onset=new ArrayList<>();if(s.days==30)for(Map.Entry<Integer,Episode> e:selected.entrySet())if(e.getKey()>=-27&&e.getKey()<=0&&!e.getValue().clock)onset.add(e.getValue());Double angle=null,deviation=null;if(onset.size()>=14){double sin=0,cos=0;for(Episode e:onset){int minutes=Instant.ofEpochSecond(e.enter).atZone(s.zone).toLocalTime().toSecondOfDay()/60;double anchor=((minutes-720+720)%1440+1440)%1440-720;double theta=2*Math.PI*anchor/1440;sin+=Math.sin(theta);cos+=Math.cos(theta);}double r=Math.min(1,Math.max(0,Math.hypot(sin,cos)/onset.size()));if(r>1e-6){angle=Math.atan2(sin,cos)*1440/(2*Math.PI);deviation=Math.sqrt(Math.max(0,-2*Math.log(r)))*1440/(2*Math.PI);}}b.metric(domain,"period.onsetEligibleDays",onset.size(),"days","known_zone_no_clock_shift_last_28_days",onset.size());b.metric(domain,"period.onsetCircularMeanAnchorMinutes",round(angle,1),"minutesFromLocalNoon","atan2_sum_sin_sum_cos",onset.size());b.metric(domain,"period.onsetCircularStdDevMinutes",round(deviation,1),"minutes","sqrt_minus_2_ln_resultant",onset.size());b.question(domain,"SLEEP_RECORDED_STAGES","SLEEP_DATA_COMPLETENESS");if(comparison)b.question(domain,"SLEEP_OBSERVED_DURATION_CHANGE");if(angle!=null)b.question(domain,"SLEEP_ONSET_REGULARITY");}
    private static void workoutHeartPeriod(AnalysisSnapshot.Builder b,JSONObject domain){List<Double> values=new ArrayList<>();Set<Integer> days=new HashSet<>();int sessions=0,excluded=0,gaps=0;for(JSONObject workout:b.source.workouts){if(!"SAVED".equals(workout.optString("status"))||!ExpansionModels.PHONE.equals(workout.optString("source")))continue;int day=b.selection.index(AnalysisSnapshot.workoutDate(workout,b.selection.zone));if(!b.selection.current(day))continue;String id=workout.optString("id");Map<String,JSONObject> segments=new HashMap<>();for(JSONObject segment:b.source.segments.getOrDefault(id,Collections.emptyList()))segments.put(segment.optString("id"),segment);int count=0;Set<String> unique=new HashSet<>();for(JSONObject observation:b.source.observations.getOrDefault(id,Collections.emptyList())){if(!"HEART".equals(observation.optString("kind")))continue;Double value=AnalysisSnapshot.validNumber(observation,"value",20,300);Long at=AnalysisSnapshot.number(observation,"measuredAt",1,253402300799999L);JSONObject segment=segments.get(observation.optString("segmentId"));Long start=segment==null?null:AnalysisSnapshot.number(segment,"startAt",1,253402300799999L),end=segment==null?null:AnalysisSnapshot.number(segment,"endAt",1,253402300799999L);if(end==null&&segment!=null)end=AnalysisSnapshot.number(segment,"lastAt",1,253402300799999L);if(!"ACCEPTED".equals(observation.optString("state"))||!"VALID".equals(observation.optString("quality"))||!"bpm".equals(observation.optString("unit"))||value==null||at==null||start==null||end==null||at<start||at>end||!unique.add(at+":"+observation.optString("rawSha256"))){excluded++;continue;}values.add(value);count++;}if(count>0){sessions++;days.add(day);if(workout.optBoolean("recoveryGapUnknown"))gaps++;}}
        b.metric(domain,"period.workoutSampleCount",values.size(),"count","accepted_heart_points_in_active_segments_separate_from_tsdb",values.size());b.metric(domain,"period.workoutObservedDays",days.size(),"days","registered_workout_heart_observation_days",days.size());b.metric(domain,"period.workoutSessionCount",sessions,"count","saved_sessions_with_valid_heart_observations",sessions);b.metric(domain,"period.workoutMeanBpm",round(mean(values),1),"bpm","pooled_active_segment_sample_mean_not_time_weighted",values.size());b.metric(domain,"period.workoutMaxBpm",values.isEmpty()?null:round(Collections.max(values),1),"bpm","maximum_registered_active_segment_point",values.size());b.metric(domain,"period.workoutExcludedRecordCount",excluded,"count","conflicts_unknown_times_and_outside_segment_exclusions",excluded);b.metric(domain,"period.workoutRecoveryGapSessionCount",gaps,"count","sessions_with_unknown_gaps",sessions);if(!values.isEmpty()&&"INSUFFICIENT".equals(b.ceilings.get("heart"))){b.ceilings.put("heart","LIMITED");NutritionModels.put(domain,"qualityCeiling","LIMITED");NutritionModels.put(domain,"availability","PARTIAL");}}
    private AnalysisHealthSummary(){}
}


